\section*{Question 6}

The function \(f\) is differentiable for all real numbers. The point \(\left(3, \frac{1}{4}\right)\) is on the graph of \(y=f(x)\), and the slope at each point \((x, y)\) on the graph is given by \(\frac{d y}{d x}=y^{2}(6-2 x)\).
\begin{itemize}
\item[(a)] Find \(\frac{d^{2} y}{d x^{2}}\) and evaluate it at the point \(\left(3, \frac{1}{4}\right)\).
\item[(b)] Find \(y=f(x)\) by solving the differential equation \(\frac{d y}{d x}=y^{2}(6-2 x)\) with the initial condition \(f(3)=\frac{1}{4}\).
\item[(a)]
\[
\begin{aligned}
& \frac{d^{2} y}{d x^{2}}=2 y \frac{d y}{d x}(6-2 x)-2 y^{2} \\
& \quad=2 y^{3}(6-2 x)^{2}-2 y^{2} \\
& \left.\frac{d^{2} y}{d x^{2}}\right|_{\left(3, \frac{1}{4}\right)}=0-2\left(\frac{1}{4}\right)^{2}=-\frac{1}{8}
\end{aligned}
\]
\item[(b)]
\[
\begin{aligned}
& \frac{1}{y^{2}} d y=(6-2 x) d x \\
& -\frac{1}{y}=6 x-x^{2}+C \\
& -4=18-9+C=9+C \\
& C=-13 \\
& y=\frac{1}{x^{2}-6 x+13}
\end{aligned}
\]
\end{itemize}
\(3:\left\{\begin{array}{l}2: \frac{d^{2} y}{d x^{2}} \\ \quad<-2>\text { product rule or } \\ \quad \text { chain rule error } \\ 1: \text { value at }\left(3, \frac{1}{4}\right)\end{array}\right.\)
\(6:\left\{\begin{array}{l}1: \text { separates variables } \\ 1: \text { antiderivative of } d y \text { term } \\ 1: \text { antiderivative of } d x \text { term } \\ 1: \text { constant of integration } \\ 1: \text { uses initial condition } f(3)=\frac{1}{4} \\ 1: \text { solves for } y\end{array}\right.\)

